<span class="line"><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> table_schema </span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw"> &#39;your_db&#39;</span><span class="__shiki_140thh">;</span></span>
